import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum UserRole {
  ADMIN = 'ADMIN',
  MANAGER = 'MANAGER',
  ITP_OPERATOR = 'ITP_OPERATOR',
  DEPOT_OPERATOR = 'DEPOT_OPERATOR',
  EXECUTIVE = 'EXECUTIVE',
  COMMERCIAL = 'COMMERCIAL'
}

export interface User {
  id: string;
  name: string;
  role: UserRole;
  avatar: string;
}

export enum FuelType {
  JET_A1 = 'Jet A-1',
  DIESEL = 'Diesel',
  PETROL = 'Petrol'
}

export interface Tank {
  id: string;
  name: string;
  type: FuelType;
  capacity: number;
  currentLevel: number; // Liters
  safeMinLevel: number;
  lastUpdated: string;
}

export interface FlightLog {
  id: string;
  flightNumber: string;
  aircraftReg: string;
  aircraftType: string;
  stand: string;
  operatorId: string;
  status: 'PENDING' | 'IN_PROGRESS' | 'COMPLETED';

  // Timestamps
  timestampPosition?: string;
  timestampStart?: string;
  timestampEnd?: string;
  timestampClearance?: string;

  // Metering
  meterOpen?: number;
  meterClose?: number;
  volume: number;

  // QC
  waterCheckPassed: boolean;
  visualCheckPassed: boolean;
}

export interface ForecastScenario {
  id: string;
  name: string; // Nominal, Upper, Lower
  description: string;
  data: { day: string; stockLevel: number; threshold: number }[];
}

export interface Alert {
  id: string;
  severity: 'low' | 'medium' | 'critical';
  message: string;
  timestamp: string;
  acknowledged: boolean;
}

