import React from 'react';
import { User, UserRole } from '../types';
import { 
  LayoutDashboard, 
  Plane, 
  Droplet, 
  TrendingUp, 
  Settings, 
  FileText, 
  LogOut,
  AlertTriangle,
  Database
} from 'lucide-react';

interface SidebarProps {
  user: User;
  activeView: string;
  setActiveView: (view: string) => void;
  onLogout: () => void;
  isMobileMenuOpen: boolean;
}

export const Sidebar: React.FC<SidebarProps> = ({ user, activeView, setActiveView, onLogout, isMobileMenuOpen }) => {
  const getMenuItems = () => {
    switch (user.role) {
      case UserRole.ITP_OPERATOR:
        return [
          { id: 'dashboard', label: 'My Tasks', icon: LayoutDashboard },
          { id: 'intoplane', label: 'Flight Refueling', icon: Plane },
          { id: 'history', label: 'Log History', icon: FileText },
        ];
      case UserRole.DEPOT_OPERATOR:
        return [
          { id: 'dashboard', label: 'Depot Status', icon: LayoutDashboard },
          { id: 'stock', label: 'Tank Levels', icon: Database },
          { id: 'bridging', label: 'Refueler Loading', icon: Droplet },
          { id: 'marine', label: 'Tanker Discharge', icon: Droplet },
        ];
      case UserRole.EXECUTIVE:
      case UserRole.COMMERCIAL:
        return [
          { id: 'dashboard', label: 'Executive Overview', icon: LayoutDashboard },
          { id: 'forecasting', label: 'Forecasting & Trends', icon: TrendingUp },
          { id: 'reports', label: 'Commercial Reports', icon: FileText },
        ];
      case UserRole.MANAGER:
      case UserRole.ADMIN:
      default:
        return [
          { id: 'dashboard', label: 'Ops Dashboard', icon: LayoutDashboard },
          { id: 'intoplane', label: 'Into-Plane Ops', icon: Plane },
          { id: 'stock', label: 'Stock Management', icon: Database },
          { id: 'forecasting', label: 'Forecasting', icon: TrendingUp },
          { id: 'admin', label: 'System Admin', icon: Settings },
        ];
    }
  };

  const menuItems = getMenuItems();

  return (
    <aside className={`
      fixed inset-y-0 left-0 z-50 w-64 bg-aviation-900 text-white transform transition-transform duration-300 ease-in-out
      ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0 lg:static lg:inset-0 shadow-xl
    `}>
      <div className="h-full flex flex-col">
        {/* Brand */}
        <div className="h-16 flex items-center px-6 bg-aviation-800 font-bold text-xl tracking-wider border-b border-aviation-700">
          <Plane className="w-6 h-6 mr-2 text-aviation-500" />
          SKYFUEL <span className="text-aviation-500 ml-1">FMS</span>
        </div>

        {/* User Profile Snippet */}
        <div className="p-6 border-b border-aviation-800 bg-aviation-800/50">
          <div className="flex items-center space-x-3">
            <img src={user.avatar} alt="User" className="w-10 h-10 rounded-full border-2 border-aviation-500" />
            <div>
              <p className="font-semibold text-sm">{user.name}</p>
              <p className="text-xs text-aviation-200 capitalize">{user.role.replace('_', ' ')}</p>
            </div>
          </div>
        </div>

        {/* Navigation */}
        <nav className="flex-1 px-4 py-6 space-y-1 overflow-y-auto">
          {menuItems.map((item) => {
            const Icon = item.icon;
            const isActive = activeView === item.id;
            return (
              <button
                key={item.id}
                onClick={() => setActiveView(item.id)}
                className={`w-full flex items-center px-4 py-3 text-sm font-medium rounded-lg transition-colors
                  ${isActive 
                    ? 'bg-aviation-600 text-white shadow-md' 
                    : 'text-aviation-100 hover:bg-aviation-800 hover:text-white'
                  }`}
              >
                <Icon className="w-5 h-5 mr-3" />
                {item.label}
              </button>
            );
          })}
        </nav>

        {/* System Status / Logout */}
        <div className="p-4 border-t border-aviation-800 bg-aviation-900">
           {/* Mock Alert Status */}
          <div className="mb-4 flex items-center px-4 py-2 bg-aviation-800 rounded-md text-xs text-yellow-400">
            <AlertTriangle className="w-3 h-3 mr-2" />
            <span>2 Critical Alerts Active</span>
          </div>

          <button
            onClick={onLogout}
            className="w-full flex items-center px-4 py-2 text-sm text-aviation-200 hover:text-white hover:bg-aviation-800 rounded-lg transition-colors"
          >
            <LogOut className="w-5 h-5 mr-3" />
            Sign Out
          </button>
        </div>
      </div>
    </aside>
  );
};

import React, { useState, useEffect } from 'react';
import { FlightLog } from '../types';
import { Clock, CheckCircle, AlertOctagon, Save, MapPin } from 'lucide-react';

export const IntoPlane: React.FC = () => {
  const [activeFlight, setActiveFlight] = useState<Partial<FlightLog> | null>(null);
  const [step, setStep] = useState<number>(1);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Mock initial selection
  const startJob = () => {
    setActiveFlight({
      flightNumber: 'SQ432',
      aircraftReg: '9V-SKT',
      aircraftType: 'A350-900',
      stand: 'F55',
      status: 'PENDING',
      meterOpen: 0,
      volume: 0,
      visualCheckPassed: false,
      waterCheckPassed: false,
    });
    setStep(1);
  };

  const handleTimestamp = (field: keyof FlightLog) => {
    setActiveFlight(prev => ({
      ...prev,
      [field]: new Date().toISOString()
    }));
  };

  const handleInputChange = (field: keyof FlightLog, value: any) => {
    setActiveFlight(prev => {
      const updated = { ...prev, [field]: value };
      if (field === 'meterClose' && updated.meterOpen !== undefined) {
        updated.volume = (value as number) - updated.meterOpen;
      }
      return updated;
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!activeFlight?.meterClose || !activeFlight.waterCheckPassed) {
      setError("Please complete all meter readings and QC checks.");
      return;
    }
    setError(null);
    setLoading(true);
    // Simulate submission
    setTimeout(() => {
      setLoading(false);
      setActiveFlight(null);
      setStep(1);
      alert("Fueling Log Submitted Successfully. Data cached offline if needed.");
    }, 1500);
  };

  if (!activeFlight) {
    return (
      <div className="p-6 max-w-4xl mx-auto">
        <h2 className="text-2xl font-bold text-aviation-900 mb-6">Assigned Jobs</h2>
        <div className="grid gap-4">
          {['SQ432 (F55) - A350', 'UL102 (C12) - A320', 'EK659 (D14) - B777'].map((job, idx) => (
            <button 
              key={idx}
              onClick={startJob}
              className="flex items-center justify-between p-6 bg-white border border-gray-200 rounded-xl shadow-sm hover:border-aviation-500 hover:shadow-md transition-all group"
            >
              <div className="flex items-center space-x-4">
                <div className="bg-aviation-100 p-3 rounded-full group-hover:bg-aviation-200">
                  <Clock className="w-6 h-6 text-aviation-600" />
                </div>
                <div className="text-left">
                  <h3 className="font-bold text-lg text-slate-800">{job}</h3>
                  <p className="text-slate-500">Scheduled: 14:00 | Est. Uplift: 45,000L</p>
                </div>
              </div>
              <span className="px-4 py-2 bg-aviation-600 text-white rounded-lg font-medium">Start</span>
            </button>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="p-4 lg:p-8 max-w-3xl mx-auto">
      {/* Header */}
      <div className="mb-8 flex justify-between items-start bg-white p-6 rounded-xl shadow-sm border border-gray-200">
        <div>
          <h2 className="text-3xl font-extrabold text-aviation-900">{activeFlight.flightNumber}</h2>
          <div className="flex space-x-4 mt-2 text-slate-600 font-medium">
            <span className="flex items-center"><MapPin className="w-4 h-4 mr-1"/> Stand {activeFlight.stand}</span>
            <span>{activeFlight.aircraftReg} ({activeFlight.aircraftType})</span>
          </div>
        </div>
        <div className="text-right">
          <span className="inline-block px-3 py-1 bg-yellow-100 text-yellow-800 rounded-full text-xs font-bold uppercase tracking-wide">
            In Progress
          </span>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">

        {/* Step 1: Arrival & QC */}
        <div className={`transition-all ${step === 1 ? 'block' : 'hidden'}`}>
           <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-200 space-y-6">
            <h3 className="text-lg font-semibold border-b pb-2 text-slate-700">1. Arrival & Safety Checks</h3>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <button 
                type="button"
                onClick={() => handleTimestamp('timestampPosition')}
                disabled={!!activeFlight.timestampPosition}
                className={`p-4 rounded-lg border-2 flex flex-col items-center justify-center h-32 transition-colors ${activeFlight.timestampPosition ? 'bg-green-50 border-green-500 text-green-700' : 'border-dashed border-gray-300 hover:border-aviation-500'}`}
              >
                <MapPin className="w-8 h-8 mb-2" />
                <span className="font-bold">{activeFlight.timestampPosition ? new Date(activeFlight.timestampPosition).toLocaleTimeString() : 'Log Position Time'}</span>
              </button>

              <div className="space-y-3">
                 <label className="flex items-center p-4 border rounded-lg hover:bg-slate-50 cursor-pointer">
                    <input 
                      type="checkbox" 
                      className="w-6 h-6 text-aviation-600 rounded focus:ring-aviation-500"
                      checked={activeFlight.visualCheckPassed}
                      onChange={(e) => handleInputChange('visualCheckPassed', e.target.checked)}
                    />
                    <span className="ml-3 font-medium">Visual Check Passed (Clear & Bright)</span>
                 </label>
                 <label className="flex items-center p-4 border rounded-lg hover:bg-slate-50 cursor-pointer">
                    <input 
                      type="checkbox" 
                      className="w-6 h-6 text-aviation-600 rounded focus:ring-aviation-500"
                      checked={activeFlight.waterCheckPassed}
                      onChange={(e) => handleInputChange('waterCheckPassed', e.target.checked)}
                    />
                    <span className="ml-3 font-medium">CWD/Water Check Passed</span>
                 </label>
              </div>
            </div>

            <div className="flex justify-end pt-4">
               <button 
                 type="button" 
                 onClick={() => setStep(2)}
                 className="px-6 py-3 bg-aviation-600 text-white rounded-lg font-bold hover:bg-aviation-700"
               >
                 Next: Metering
               </button>
            </div>
           </div>
        </div>

        {/* Step 2: Metering */}
        <div className={`transition-all ${step === 2 ? 'block' : 'hidden'}`}>
          <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-200 space-y-6">
            <h3 className="text-lg font-semibold border-b pb-2 text-slate-700">2. Fueling Operations</h3>

            <div className="grid grid-cols-2 gap-4">
               <button 
                  type="button"
                  onClick={() => handleTimestamp('timestampStart')}
                  disabled={!!activeFlight.timestampStart}
                  className={`p-4 rounded-lg border-2 text-center ${activeFlight.timestampStart ? 'bg-green-50 border-green-500' : 'bg-slate-50 border-slate-200'}`}
                >
                  <span className="block text-xs uppercase text-slate-500 font-bold">Commenced</span>
                  <span className="text-xl font-mono font-bold">{activeFlight.timestampStart ? new Date(activeFlight.timestampStart).toLocaleTimeString() : '--:--'}</span>
                </button>
                <button 
                  type="button"
                  onClick={() => handleTimestamp('timestampEnd')}
                  disabled={!!activeFlight.timestampEnd}
                  className={`p-4 rounded-lg border-2 text-center ${activeFlight.timestampEnd ? 'bg-green-50 border-green-500' : 'bg-slate-50 border-slate-200'}`}
                >
                  <span className="block text-xs uppercase text-slate-500 font-bold">Completed</span>
                  <span className="text-xl font-mono font-bold">{activeFlight.timestampEnd ? new Date(activeFlight.timestampEnd).toLocaleTimeString() : '--:--'}</span>
                </button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="block text-sm font-bold text-slate-700 mb-2">Opening Meter (L)</label>
                <input 
                  type="number" 
                  className="w-full text-2xl p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-aviation-500 focus:border-aviation-500"
                  placeholder="000000"
                  value={activeFlight.meterOpen || ''}
                  onChange={(e) => handleInputChange('meterOpen', parseInt(e.target.value))}
                />
              </div>
              <div>
                <label className="block text-sm font-bold text-slate-700 mb-2">Closing Meter (L)</label>
                <input 
                  type="number" 
                  className="w-full text-2xl p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-aviation-500 focus:border-aviation-500"
                  placeholder="000000"
                  value={activeFlight.meterClose || ''}
                  onChange={(e) => handleInputChange('meterClose', parseInt(e.target.value))}
                />
              </div>
            </div>

            <div className="bg-slate-100 p-4 rounded-lg text-center">
              <span className="text-sm text-slate-500 font-bold uppercase tracking-wider">Net Volume</span>
              <div className="text-4xl font-black text-aviation-700 font-mono">
                {activeFlight.volume?.toLocaleString()} <span className="text-xl text-slate-400">L</span>
              </div>
            </div>

            {error && (
              <div className="flex items-center p-4 bg-red-50 text-red-700 rounded-lg border border-red-200">
                <AlertOctagon className="w-5 h-5 mr-2" />
                {error}
              </div>
            )}

            <div className="flex justify-between pt-4">
              <button 
                 type="button" 
                 onClick={() => setStep(1)}
                 className="px-6 py-3 text-slate-600 font-medium hover:text-slate-900"
               >
                 Back
               </button>
               <button 
                 type="submit" 
                 disabled={loading}
                 className="flex items-center px-8 py-3 bg-aviation-600 text-white rounded-lg font-bold hover:bg-aviation-700 disabled:opacity-50 shadow-lg"
               >
                 {loading ? 'Submitting...' : (
                   <>
                    <Save className="w-5 h-5 mr-2" />
                    Submit & Sync
                   </>
                 )}
               </button>
            </div>
          </div>
        </div>
      </form>
    </div>
  );
};

import React, { useState } from 'react';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, ReferenceLine 
} from 'recharts';
import { FORECAST_DATA } from '../constants';
import { RefreshCw, Download, Layers } from 'lucide-react';

export const Forecasting: React.FC = () => {
  const [activeScenarioId, setActiveScenarioId] = useState<string>('nominal');
  const activeScenario = FORECAST_DATA.find(s => s.id === activeScenarioId) || FORECAST_DATA[0];

  return (
    <div className="p-4 lg:p-8 max-w-7xl mx-auto space-y-6">
      {/* Header Controls */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-6 rounded-xl shadow-sm border border-gray-100">
        <div>
          <h2 className="text-2xl font-bold text-slate-900">Jet A-1 Stock Forecast</h2>
          <p className="text-slate-500 text-sm mt-1">Real-time depletion modeling based on live flight schedules</p>
        </div>
        <div className="flex space-x-3">
          <button className="flex items-center px-4 py-2 bg-white border border-gray-300 rounded-lg text-sm font-medium hover:bg-gray-50 text-slate-700">
            <RefreshCw className="w-4 h-4 mr-2" />
            Recalculate
          </button>
          <button className="flex items-center px-4 py-2 bg-aviation-600 text-white rounded-lg text-sm font-medium hover:bg-aviation-700 shadow-sm">
            <Download className="w-4 h-4 mr-2" />
            Export Report
          </button>
        </div>
      </div>

      {/* Scenario Toggles */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        {FORECAST_DATA.map((scenario) => (
          <button
            key={scenario.id}
            onClick={() => setActiveScenarioId(scenario.id)}
            className={`p-4 rounded-xl border-2 text-left transition-all ${
              activeScenarioId === scenario.id 
                ? 'border-aviation-500 bg-aviation-50 ring-1 ring-aviation-500' 
                : 'border-white bg-white hover:border-gray-300 shadow-sm'
            }`}
          >
            <div className="flex items-center justify-between mb-2">
              <span className={`text-xs font-bold uppercase tracking-wide px-2 py-0.5 rounded-full ${
                activeScenarioId === scenario.id ? 'bg-aviation-200 text-aviation-800' : 'bg-gray-100 text-gray-500'
              }`}>
                {scenario.name}
              </span>
              <Layers className={`w-4 h-4 ${activeScenarioId === scenario.id ? 'text-aviation-600' : 'text-gray-400'}`} />
            </div>
            <p className="text-sm text-slate-600">{scenario.description}</p>
          </button>
        ))}
      </div>

      {/* Main Forecast Chart */}
      <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
        <h3 className="text-lg font-bold text-slate-800 mb-6">30-Day Depletion Curve</h3>
        <div className="h-96 w-full">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={activeScenario.data} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
              <defs>
                <linearGradient id="colorStock" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%" stopColor="#0ea5e9" stopOpacity={0.8}/>
                  <stop offset="95%" stopColor="#0ea5e9" stopOpacity={0}/>
                </linearGradient>
              </defs>
              <XAxis dataKey="day" axisLine={false} tickLine={false} tick={{fontSize: 12, fill: '#64748b'}} />
              <YAxis 
                axisLine={false} 
                tickLine={false} 
