  const inputClass = "w-full p-2 border border-gray-300 rounded focus:ring-2 focus:ring-aviation-500 focus:border-aviation-500 bg-white text-slate-900 text-right font-mono";

  const [readings, setReadings] = useState<Record<string, number>>({});

  const handleReadingChange = (id: string, value: string) => {
    setReadings(prev => ({
        ...prev,
        [id]: parseFloat(value) || 0
    }));
  };

  return (
    <div className="p-4 lg:p-8 max-w-7xl mx-auto text-slate-900">
       <div className="mb-8 bg-white p-6 rounded-xl shadow-sm border border-gray-200 flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-aviation-900 flex items-center">
            <Database className="w-6 h-6 mr-3 text-aviation-600" />
            Depot Inventory
          </h2>
          <p className="text-slate-500 mt-1">Daily tank physical stock reconciliation</p>
        </div>
        <div className="flex items-center space-x-3">
             <span className="text-sm text-slate-500">Last Updated: Today 06:00</span>
             <button className="p-2 hover:bg-gray-100 rounded-full border border-gray-200 bg-white">
                <RefreshCw className="w-4 h-4 text-slate-600" />
             </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {TANKS.map((tank) => {
             const isLow = tank.currentLevel < tank.safeMinLevel;
             const fillPct = (tank.currentLevel / tank.capacity) * 100;
             const typeColor = tank.type === FuelType.JET_A1 ? 'bg-aviation-600' : (tank.type === FuelType.DIESEL ? 'bg-yellow-600' : 'bg-orange-600');
             const typeBadge = tank.type === FuelType.JET_A1 ? 'bg-aviation-50 text-aviation-700' : (tank.type === FuelType.DIESEL ? 'bg-yellow-50 text-yellow-700' : 'bg-orange-50 text-orange-700');

             return (
                <div key={tank.id} className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
                    <div className="p-4 border-b border-gray-100 flex justify-between items-center bg-gray-50">
                        <span className={`px-2 py-1 rounded text-xs font-bold uppercase tracking-wide border border-gray-200 ${typeBadge}`}>
                            {tank.type}
                        </span>
                        {isLow && (
                            <div className="flex items-center text-red-600 text-xs font-bold bg-red-50 px-2 py-1 rounded border border-red-200">
                                <AlertTriangle className="w-3 h-3 mr-1" />
                                LOW LEVEL
                            </div>
                        )}
                    </div>

                    <div className="p-6">
                        <h3 className="font-bold text-lg text-slate-800 mb-1">{tank.name}</h3>
                        <p className="text-xs text-slate-500 mb-4">Max Capacity: {tank.capacity.toLocaleString()} L</p>

                        <div className="flex items-end space-x-4 mb-6">
                            <div className="flex-1 h-32 bg-gray-100 rounded-lg relative overflow-hidden border border-gray-200">
                                <div 
                                    className={`absolute bottom-0 w-full transition-all duration-1000 ${typeColor}`}
                                    style={{ height: `${fillPct}%` }}
                                >
                                    <div className="absolute top-0 w-full h-1 bg-white/30"></div>
                                </div>
                            </div>
                            <div className="text-right">
                                <span className="block text-3xl font-black text-slate-900">{tank.currentLevel.toLocaleString()}</span>
                                <span className="text-xs font-bold text-slate-400 uppercase">Current Liters</span>
                            </div>
                        </div>

                        <div className="space-y-3 pt-4 border-t border-gray-100">
                            <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">New Dip Reading (L)</label>
                                <input 
                                    type="number" 
                                    className={inputClass}
                                    placeholder={tank.currentLevel.toString()}
                                    onChange={(e) => handleReadingChange(tank.id, e.target.value)}
                                />
                            </div>
                            <div className="grid grid-cols-2 gap-3">
                                <div>
                                    <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Temp (°C)</label>
                                    <input type="number" className={inputClass} placeholder="15.0" />
                                </div>
                                <div>
                                    <label className="block text-xs font-bold text-slate-500 uppercase mb-1">SG</label>
                                    <input type="number" className={inputClass} placeholder="0.8000" />
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
             );
        })}
      </div>

      <div className="mt-8 flex justify-end">
          <button className="flex items-center px-8 py-3 bg-slate-900 text-white rounded-xl font-bold hover:bg-slate-800 shadow-lg">
              <Save className="w-5 h-5 mr-2" />
              Save Inventory
          </button>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Sidebar } from './components/Sidebar';
import { Dashboard } from './components/Dashboard';
import { IntoPlane } from './components/IntoPlane';
import { Forecasting } from './components/Forecasting';
import { Bridging } from './components/Bridging';
import { TankerDischarge } from './components/TankerDischarge';
import { Stock } from './components/Stock';
import { MOCK_USERS } from './constants';
import { User, UserRole } from './types';
import { Wifi, WifiOff, Menu, X } from 'lucide-react';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User>(MOCK_USERS[0]); // Default Admin
  const [activeView, setActiveView] = useState('dashboard');
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  // Network listener
  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // View Router
  const renderContent = () => {
    switch (activeView) {
      case 'dashboard':
        return <Dashboard />;
      case 'intoplane':
        return <IntoPlane />;
      case 'forecasting':
        return <Forecasting />;
      case 'bridging':
        return <Bridging />;
      case 'marine':
        return <TankerDischarge />;
      case 'stock':
        return <Stock />;
      default:
        return (
          <div className="flex items-center justify-center h-full text-slate-400">
            <p>Module under construction: {activeView}</p>
          </div>
        );
    }
  };

  // Demo Login Switcher (for presentation only)
  const handleRoleSwitch = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const user = MOCK_USERS.find(u => u.id === e.target.value);
    if (user) {
      setCurrentUser(user);
      // Reset view to dashboard when switching roles, unless it's a specific operator
      if (user.role === UserRole.ITP_OPERATOR) {
        setActiveView('intoplane');
      } else if (user.role === UserRole.DEPOT_OPERATOR) {
        setActiveView('bridging');
      } else {
        setActiveView('dashboard');
      }
    }
  };

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden text-slate-900">
      {/* Sidebar */}
      <Sidebar 
        user={currentUser} 
        activeView={activeView} 
        setActiveView={(view) => {
          setActiveView(view);
          setIsMobileMenuOpen(false);
        }}
        onLogout={() => alert('Logged out')}
        isMobileMenuOpen={isMobileMenuOpen}
      />

      {/* Main Content Wrapper */}
      <div className="flex-1 flex flex-col min-w-0 overflow-hidden">

        {/* Top Header */}
        <header className="h-16 bg-white border-b border-gray-200 flex items-center justify-between px-4 lg:px-8">
          <div className="flex items-center">
            <button 
              onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
              className="lg:hidden mr-4 text-slate-500"
            >
              {isMobileMenuOpen ? <X /> : <Menu />}
            </button>
            <h1 className="text-xl font-bold text-slate-800 capitalize hidden sm:block">
              {activeView.replace('_', ' ')}
            </h1>
          </div>

          <div className="flex items-center space-x-4">
             {/* Offline Indicator */}
             <div className={`flex items-center px-3 py-1 rounded-full text-xs font-bold ${isOnline ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                {isOnline ? <Wifi className="w-3 h-3 mr-1"/> : <WifiOff className="w-3 h-3 mr-1"/>}
                {isOnline ? 'ONLINE' : 'OFFLINE MODE'}
             </div>

             {/* Role Switcher for Demo */}
             <select 
               className="text-sm border-gray-300 rounded-md shadow-sm focus:border-aviation-500 focus:ring-aviation-500 bg-white text-slate-900"
               value={currentUser.id}
               onChange={handleRoleSwitch}
             >
               {MOCK_USERS.map(u => (
                 <option key={u.id} value={u.id}>{u.name} ({u.role})</option>
               ))}
             </select>
          </div>
        </header>

        {/* Main Content Scroll Area */}
        <main className="flex-1 overflow-y-auto">
          {renderContent()}
        </main>
      </div>

      {/* Mobile Overlay */}
      {isMobileMenuOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-40 lg:hidden"
          onClick={() => setIsMobileMenuOpen(false)}
        />
      )}
    </div>
  );
};

export default App;

export enum UserRole {
  ADMIN = 'ADMIN',
  ITP_MANAGER = 'ITP_MANAGER',
  DEPOT_MANAGER = 'DEPOT_MANAGER',
  ITP_OPERATOR = 'ITP_OPERATOR',
  DEPOT_OPERATOR = 'DEPOT_OPERATOR',
  EXECUTIVE = 'EXECUTIVE',
  COMMERCIAL = 'COMMERCIAL'
}

export interface User {
  id: string;
  name: string;
  role: UserRole;
  avatar: string;
}

export enum FuelType {
  JET_A1 = 'Jet A-1',
  DIESEL = 'Diesel',
  PETROL = 'Petrol'
}

export interface Tank {
  id: string;
  name: string;
  type: FuelType;
  capacity: number;
  currentLevel: number; // Liters
  safeMinLevel: number;
  lastUpdated: string;
}

export interface FlightLog {
  id: string;
  flightNumber: string;
  aircraftReg: string;
  aircraftType: string;
  stand: string;
  operatorId: string;
  status: 'PENDING' | 'IN_PROGRESS' | 'COMPLETED';

  // Granular Timestamps
  timestampArrived?: string;      // Arrived at Stand
  timestampPosition?: string;     // Positioned at Aircraft
  timestampStart?: string;        // Commenced Pumping
  timestampInitialEnd?: string;   // Initial Stop
  timestampFinalStart?: string;   // Top-up Start (Optional)
  timestampFinalEnd?: string;     // Final Stop / Completed
  timestampClearance?: string;    // Documents signed, leaving safety zone

  // Metering
  meterOpen?: number;
  meterClose?: number;
  volume: number;

  // QC
  waterCheckPassed: boolean;
  visualCheckPassed: boolean;
}

export interface BridgingLog {
  id: string;
  sourceTankId: string;
  vehicleId: string;
  volume: number;
  startTime: string;
  endTime: string;
  visualCheckPassed: boolean;
  cwdCheckPassed: boolean;
  density?: number;
  temperature?: number;
  operatorId: string;
}

export interface ForecastScenario {
  id: string;
  name: string; // Nominal, Upper, Lower
  description: string;
  data: { day: string; stockLevel: number; threshold: number }[];
}

export interface Alert {
  id: string;
  severity: 'low' | 'medium' | 'critical';
  message: string;
  timestamp: string;
  acknowledged: boolean;
}

