import React, { useState } from 'react';
import { FlightLog } from '../types';
import { Clock, AlertOctagon, Save, MapPin, Truck, Play, Pause, CheckSquare, RotateCw } from 'lucide-react';

export const IntoPlane: React.FC = () => {
  const [activeFlight, setActiveFlight] = useState<Partial<FlightLog> | null>(null);
  const [step, setStep] = useState<number>(1);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [showTopUp, setShowTopUp] = useState(false);

  // High contrast inputs for outdoor visibility
  const inputClass = "w-full text-2xl p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-aviation-500 focus:border-aviation-500 bg-white text-slate-900 placeholder:text-slate-400 font-mono";

  // Mock initial selection
  const startJob = () => {
    setActiveFlight({
      flightNumber: 'SQ432',
      aircraftReg: '9V-SKT',
      aircraftType: 'A350-900',
      stand: 'F55',
      status: 'PENDING',
      meterOpen: 0,
      volume: 0,
      visualCheckPassed: false,
      waterCheckPassed: false,
    });
    setStep(1);
    setShowTopUp(false);
  };

  const handleTimestamp = (field: keyof FlightLog) => {
    setActiveFlight(prev => ({
      ...prev,
      [field]: new Date().toISOString()
    }));
  };

  const handleInputChange = (field: keyof FlightLog, value: any) => {
    setActiveFlight(prev => {
      const updated = { ...prev, [field]: value };
      if (field === 'meterClose' && updated.meterOpen !== undefined) {
        updated.volume = (value as number) - updated.meterOpen;
      }
      return updated;
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!activeFlight?.meterClose || !activeFlight.waterCheckPassed) {
      setError("Please complete all meter readings and QC checks.");
      return;
    }
    if (!activeFlight.timestampFinalEnd || !activeFlight.timestampClearance) {
      setError("Please complete all operational timings including Clearance.");
      return;
    }
    setError(null);
    setLoading(true);
    // Simulate submission
    setTimeout(() => {
      setLoading(false);
      setActiveFlight(null);
      setStep(1);
      alert("Fueling Log Submitted Successfully. Data cached offline if needed.");
    }, 1500);
  };

  if (!activeFlight) {
    return (
      <div className="p-6 max-w-4xl mx-auto">
        <h2 className="text-2xl font-bold text-aviation-900 mb-6">Assigned Jobs</h2>
        <div className="grid gap-4">
          {['SQ432 (F55) - A350', 'UL102 (C12) - A320', 'EK659 (D14) - B777'].map((job, idx) => (
            <button 
              key={idx}
              onClick={startJob}
              className="flex items-center justify-between p-6 bg-white border border-gray-200 rounded-xl shadow-sm hover:border-aviation-500 hover:shadow-md transition-all group"
            >
              <div className="flex items-center space-x-4">
                <div className="bg-aviation-100 p-3 rounded-full group-hover:bg-aviation-200">
                  <Clock className="w-6 h-6 text-aviation-600" />
                </div>
                <div className="text-left">
                  <h3 className="font-bold text-lg text-slate-800">{job}</h3>
                  <p className="text-slate-500">Scheduled: 14:00 | Est. Uplift: 45,000L</p>
                </div>
              </div>
              <span className="px-4 py-2 bg-aviation-600 text-white rounded-lg font-medium">Start</span>
            </button>
          ))}
        </div>
      </div>
    );
  }

  const TimeButton = ({ label, field, icon: Icon, colorClass = "text-slate-600", disabled = false }: any) => {
    const timeValue = activeFlight[field as keyof FlightLog];
    const isSet = !!timeValue;

    return (
        <button 
            type="button"
            onClick={() => handleTimestamp(field as keyof FlightLog)}
            disabled={disabled || isSet}
            className={`p-3 rounded-lg border-2 flex flex-col items-center justify-center transition-all w-full
                ${isSet 
                    ? 'bg-green-50 border-green-500 text-green-700' 
                    : disabled 
                        ? 'bg-gray-50 border-gray-200 text-gray-300 cursor-not-allowed' 
                        : 'bg-white border-dashed border-gray-300 hover:border-aviation-500 hover:bg-aviation-50'
                }
            `}
        >
            <Icon className={`w-6 h-6 mb-1 ${isSet ? 'text-green-600' : colorClass}`} />
            <span className="text-xs font-bold uppercase tracking-wide">{label}</span>
            <span className="font-mono font-bold text-sm mt-1">
                {isSet ? new Date(timeValue as string).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}) : '--:--'}
            </span>
        </button>
    );
  }

  return (
    <div className="p-4 lg:p-8 max-w-4xl mx-auto">
      {/* Header */}
      <div className="mb-8 flex justify-between items-start bg-white p-6 rounded-xl shadow-sm border border-gray-200">
        <div>
          <h2 className="text-3xl font-extrabold text-aviation-900">{activeFlight.flightNumber}</h2>
          <div className="flex space-x-4 mt-2 text-slate-600 font-medium">
            <span className="flex items-center"><MapPin className="w-4 h-4 mr-1"/> Stand {activeFlight.stand}</span>
            <span>{activeFlight.aircraftReg} ({activeFlight.aircraftType})</span>
          </div>
        </div>
        <div className="text-right">
          <span className="inline-block px-3 py-1 bg-yellow-100 text-yellow-800 rounded-full text-xs font-bold uppercase tracking-wide">
            In Progress
          </span>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">

        {/* Step 1: Timestamps & QC */}
        <div className={`transition-all ${step === 1 ? 'block' : 'hidden'}`}>
           <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-200 space-y-6">
            <h3 className="text-lg font-semibold border-b pb-2 text-slate-700">1. Operations Timing & Safety</h3>

            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                <TimeButton label="Arrived" field="timestampArrived" icon={Truck} />
                <TimeButton label="Positioned" field="timestampPosition" icon={MapPin} disabled={!activeFlight.timestampArrived} />
                <TimeButton label="Commenced" field="timestampStart" icon={Play} disabled={!activeFlight.timestampPosition} />
                <TimeButton label="Initial Stop" field="timestampInitialEnd" icon={Pause} disabled={!activeFlight.timestampStart} />
            </div>

            {/* Optional Top Up Section */}
            {activeFlight.timestampInitialEnd && (
                <div className="bg-slate-50 p-4 rounded-lg border border-slate-200">
                    <div className="flex items-center justify-between mb-4">
                        <span className="text-sm font-bold text-slate-700">Top-up Required?</span>
                        <button 
                            type="button" 
                            onClick={() => setShowTopUp(!showTopUp)}
                            className="text-sm text-aviation-600 font-bold hover:underline"
                        >
                            {showTopUp ? 'Cancel Top-up' : 'Add Top-up Timings'}
                        </button>
                    </div>
                    {showTopUp && (
                        <div className="grid grid-cols-2 gap-4 animate-in fade-in slide-in-from-top-2">
                             <TimeButton label="Top-up Start" field="timestampFinalStart" icon={RotateCw} />
                             <TimeButton label="Top-up End" field="timestampFinalEnd" icon={CheckSquare} disabled={!activeFlight.timestampFinalStart} />
                        </div>
                    )}
                </div>
            )}

            <div className="grid grid-cols-2 md:grid-cols-2 gap-4">
                 <TimeButton 
                    label="Completed" 
                    field="timestampFinalEnd" 
                    icon={CheckSquare} 
                    disabled={!activeFlight.timestampInitialEnd || (showTopUp && !activeFlight.timestampFinalStart)} 
                 />
                 <TimeButton 
                    label="Clearance" 
                    field="timestampClearance" 
                    icon={Truck} 
                    disabled={!activeFlight.timestampFinalEnd} 
                 />
            </div>

            <hr className="border-gray-200" />

            <h4 className="font-bold text-slate-700">Safety & Quality Checks</h4>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                 <label className={`flex items-center p-4 border rounded-lg cursor-pointer transition-colors ${activeFlight.visualCheckPassed ? 'bg-green-50 border-green-200' : 'bg-white hover:bg-slate-50'}`}>
                    <input 
                      type="checkbox" 
                      className="w-6 h-6 text-aviation-600 rounded focus:ring-aviation-500"
                      checked={activeFlight.visualCheckPassed}
                      onChange={(e) => handleInputChange('visualCheckPassed', e.target.checked)}
                    />
                    <span className="ml-3 font-medium text-slate-800">Visual Check Passed (Clear & Bright)</span>
                 </label>
                 <label className={`flex items-center p-4 border rounded-lg cursor-pointer transition-colors ${activeFlight.waterCheckPassed ? 'bg-green-50 border-green-200' : 'bg-white hover:bg-slate-50'}`}>
                    <input 
                      type="checkbox" 
                      className="w-6 h-6 text-aviation-600 rounded focus:ring-aviation-500"
                      checked={activeFlight.waterCheckPassed}
                      onChange={(e) => handleInputChange('waterCheckPassed', e.target.checked)}
                    />
                    <span className="ml-3 font-medium text-slate-800">CWD/Water Check Passed</span>
                 </label>
            </div>

            <div className="flex justify-end pt-4">
               <button 
                 type="button" 
                 onClick={() => setStep(2)}
                 disabled={!activeFlight.timestampStart}
                 className="px-6 py-3 bg-aviation-600 text-white rounded-lg font-bold hover:bg-aviation-700 disabled:opacity-50 disabled:cursor-not-allowed"
