                        ? 'bg-green-50 border-green-500' 
                        : !activeFlight?.timestampPosition
                            ? 'bg-slate-100 border-slate-200 opacity-50'
                            : 'bg-white border-slate-200 active:border-aviation-500 active:bg-aviation-50'}
