                               onChange={(e) => handleInputChange(check.id as keyof FlightLog, e.target.checked)}
                               className="toggle-checkbox absolute block w-6 h-6 rounded-full bg-white border-4 border-gray-300 appearance-none cursor-pointer transition-transform duration-200 ease-in-out checked:translate-x-6 checked:border-green-500"
                           />
                           <span className={`toggle-label block overflow-hidden h-8 rounded-full cursor-pointer ${activeFlight?.[check.id as keyof FlightLog] ? 'bg-green-500' : 'bg-gray-300'}`}></span>
                       </div>
                   </label>
               ))}
           </div>

           <div className="mt-8">
               <button 
                    onClick={() => handleTimestamp('timestampClearance')}
                    disabled={!!activeFlight?.timestampClearance}
                    className={`w-full p-6 rounded-xl border-4 font-black text-xl uppercase tracking-wide flex items-center justify-center mb-6
