                   {activeFlight?.timestampClearance ? 'CLEARED' : 'LOG CLEARANCE'}
                   {activeFlight?.timestampClearance && <CheckCircle className="ml-3 w-6 h-6" />}
               </button>

               <div className="flex space-x-4">
                    <button onClick={() => setCurrentScreen('metering')} className="flex-1 py-4 bg-gray-200 rounded-xl font-bold text-slate-600">Back</button>
                    <button 
                        onClick={handleSubmit}
                        disabled={loading || !activeFlight?.timestampClearance || !activeFlight?.waterCheck}
                        className="flex-[2] py-4 bg-aviation-600 text-white rounded-xl font-bold shadow-xl disabled:opacity-50 flex items-center justify-center"
                    >
                        {loading ? 'SYNCING...' : 'SUBMIT JOB'}
                    </button>
               </div>
           </div>
      </div>
  );

  return (
    <div className="bg-slate-50 min-h-full pb-20 lg:pb-0">
      <MobileHeader />
      <div className="max-w-md mx-auto h-full">
        {currentScreen === 'dashboard' && <ScreenDashboard />}
        {currentScreen === 'timestamps' && <ScreenTimestamps />}
        {currentScreen === 'metering' && <ScreenMetering />}
        {currentScreen === 'qc' && <ScreenQC />}
      </div>
    </div>
  );
};

