@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');

:root {
  --glass-border: rgba(255, 255, 255, 0.5);
  --glass-bg: rgba(255, 255, 255, 0.7);
  --glass-shadow: 0 4px 30px rgba(0, 0, 0, 0.1);
}

body {
  font-family: 'Inter', sans-serif;
  background-color: #F8FAFC;
  color: #0F172A;
}

/* Tabular numbers for all data display */
.tabular-nums {
  font-variant-numeric: tabular-nums;
}

/* Custom Scrollbar */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}

::-webkit-scrollbar-track {
  background: transparent;
}

::-webkit-scrollbar-thumb {
  background: #CBD5E1;
  border-radius: 3px;
}

::-webkit-scrollbar-thumb:hover {
  background: #94A3B8;
}

/* Glassmorphism Utilities */
.glass-panel {
  background: var(--glass-bg);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid rgba(255, 255, 255, 0.6);
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05), 0 2px 4px -1px rgba(0, 0, 0, 0.03);
}

.glass-sidebar {
  background: rgba(255, 255, 255, 0.85);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-right: 1px solid rgba(226, 232, 240, 0.8);
}

/* Animations */
@keyframes pulse-ring {
  0% { transform: scale(0.8); opacity: 0.5; }
  100% { transform: scale(2.4); opacity: 0; }
}

.animate-pulse-ring {
  animation: pulse-ring 2s cubic-bezier(0.215, 0.61, 0.355, 1) infinite;
}

.loader-shimmer {
  background: #f6f7f8;
  background-image: linear-gradient(to right, #f6f7f8 0%, #edeef1 20%, #f6f7f8 40%, #f6f7f8 100%);
  background-repeat: no-repeat;
  background-size: 800px 100%; 
  animation-duration: 1s;
  animation-fill-mode: forwards; 
  animation-iteration-count: infinite;
  animation-name: placeholderShimmer;
  animation-timing-function: linear;
}

@keyframes placeholderShimmer {
  0% { background-position: -468px 0; }
  100% { background-position: 468px 0; }
}

import React, { createContext, useContext, useState, useEffect } from 'react';
import { User, UserRole, Tank, FlightLog } from '../types';
import { MOCK_USERS, TANKS, RECENT_LOGS } from '../constants';
import { toast } from 'sonner';

interface AppState {
  currentUser: User;
  tanks: Tank[];
  logs: FlightLog[];
  isOnline: boolean;
  isLoading: boolean;
  searchQuery: string;
}

interface AppContextType extends AppState {
  setUser: (user: User) => void;
  updateTankLevel: (id: string, level: number) => void;
  addLog: (log: FlightLog) => void;
  setSearchQuery: (query: string) => void;
  refreshData: () => Promise<void>;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<User>(MOCK_USERS[0]);
  const [tanks, setTanks] = useState<Tank[]>(TANKS);
  const [logs, setLogs] = useState<FlightLog[]>(RECENT_LOGS);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [isLoading, setIsLoading] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');

  // Network Listeners
  useEffect(() => {
    const handleOnline = () => {
      setIsOnline(true);
      toast.success('Connection restored');
    };
    const handleOffline = () => {
      setIsOnline(false);
      toast.warning('You are offline. Changes will sync locally.');
    };
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  const updateTankLevel = (id: string, level: number) => {
    // Optimistic Update
    setTanks(prev => prev.map(t => t.id === id ? { ...t, currentLevel: level, lastUpdated: new Date().toISOString() } : t));
    toast.success('Tank level updated', {
        description: `New Level: ${level.toLocaleString()} L`,
        duration: 2000,
    });
  };

  const addLog = (log: FlightLog) => {
    setLogs(prev => [log, ...prev]);
    toast.success('Operation Logged', {
        description: `Flight ${log.flightNumber} - ${log.status}`,
    });
  };

  const setUser = (user: User) => {
    setIsLoading(true);
    // Simulate auth latency
    setTimeout(() => {
        setCurrentUser(user);
        setIsLoading(false);
        toast.info(`Switched to ${user.role.replace('_', ' ')} view`);
    }, 600);
  };

  const refreshData = async () => {
    setIsLoading(true);
    // Simulate API fetch
    await new Promise(resolve => setTimeout(resolve, 1000));
    setIsLoading(false);
    toast.success('Data refreshed');
  };

  return (
    <AppContext.Provider value={{
      currentUser,
      tanks,
      logs,
      isOnline,
      isLoading,
      searchQuery,
      setUser,
      updateTankLevel,
      addLog,
      setSearchQuery,
      refreshData
    }}>
      {children}
    </AppContext.Provider>
  );
};

export const useAppStore = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error('useAppStore must be used within AppProvider');
  return context;
};

import React from 'react';
import { motion } from 'framer-motion';
import { FuelType } from '../types';
import clsx from 'clsx';

interface TankVisualProps {
  percentage: number;
  type: FuelType;
  width?: number;
  height?: number;
}

export const TankVisual: React.FC<TankVisualProps> = ({ percentage, type, width = 60, height = 120 }) => {
  const getColor = () => {
    switch(type) {
      case FuelType.JET_A1: return '#0ea5e9'; // aviation-500
      case FuelType.DIESEL: return '#eab308'; // yellow-500
      case FuelType.PETROL: return '#f97316'; // orange-500
      default: return '#64748b';
    }
  };

  const color = getColor();
  const fillHeight = Math.min(Math.max(percentage, 0), 100);

  return (
    <div className="relative" style={{ width, height }}>
      <svg width={width} height={height} viewBox="0 0 100 200" className="drop-shadow-sm">
        {/* Tank Body */}
        <defs>
            <linearGradient id={`grad-${type}`} x1="0%" y1="0%" x2="0%" y2="100%">
                <stop offset="0%" style={{ stopColor: color, stopOpacity: 0.8 }} />
                <stop offset="100%" style={{ stopColor: color, stopOpacity: 0.4 }} />
            </linearGradient>
            <filter id="glass" x="0" y="0" width="100%" height="100%">
                <feGaussianBlur in="SourceGraphic" stdDeviation="1" />
            </filter>
        </defs>

        {/* Background Shell */}
        <rect x="0" y="0" width="100" height="200" rx="10" fill="#f1f5f9" stroke="#cbd5e1" strokeWidth="2" />

        {/* Liquid Fill */}
        <motion.rect 
            x="2" 
            y={200 - (fillHeight * 2)} 
            width="96" 
            height={fillHeight * 2} 
            rx="8"
            fill={`url(#grad-${type})`}
            initial={{ height: 0, y: 200 }}
            animate={{ height: fillHeight * 2, y: 200 - (fillHeight * 2) }}
            transition={{ type: "spring", stiffness: 50, damping: 20 }}
        />

        {/* Measurement Lines */}
        {[25, 50, 75].map(line => (
            <line 
                key={line} 
                x1="10" 
                y1={200 - (line * 2)} 
                x2="90" 
                y2={200 - (line * 2)} 
                stroke="white" 
                strokeOpacity="0.5" 
                strokeWidth="1" 
                strokeDasharray="4 2"
            />
        ))}

        {/* Glass Reflection Highlight */}
        <path d="M5 10 Q 50 20 95 10 L 95 190 Q 50 180 5 190 Z" fill="url(#grad-glass)" opacity="0.1" style={{pointerEvents: 'none'}} />
      </svg>

      {/* Percentage Text Overlay */}
      <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
         <span className={clsx(
             "text-xs font-bold tabular-nums bg-white/80 backdrop-blur-sm px-1.5 py-0.5 rounded shadow-sm",
             percentage < 20 ? "text-red-600" : "text-slate-700"
         )}>
             {percentage.toFixed(0)}%
         </span>
      </div>
    </div>
  );
};

