import { create } from 'zustand';
import { User, Tank, FlightLog, UserRole } from './types';
import { MOCK_USERS, TANKS, RECENT_LOGS } from './constants';

interface AppState {
  user: User;
  tanks: Tank[];
  logs: FlightLog[];
  isSidebarOpen: boolean;
  isLoading: boolean;

  // Actions
  setUser: (user: User) => void;
  toggleSidebar: () => void;
  setSidebarOpen: (isOpen: boolean) => void;
  updateTankLevel: (id: string, level: number) => void;
  addLog: (log: FlightLog) => void;
  setLoading: (loading: boolean) => void;
}

export const useStore = create<AppState>((set) => ({
  user: MOCK_USERS[0], // Default to Admin
  tanks: TANKS,
  logs: RECENT_LOGS,
  isSidebarOpen: true, // Desktop default
  isLoading: false,

  setUser: (user) => set({ user }),
  toggleSidebar: () => set((state) => ({ isSidebarOpen: !state.isSidebarOpen })),
  setSidebarOpen: (isOpen) => set({ isSidebarOpen: isOpen }),

  updateTankLevel: (id, level) => set((state) => ({
    tanks: state.tanks.map(t => 
      t.id === id ? { ...t, currentLevel: level, lastUpdated: new Date().toISOString() } : t
    )
  })),

  addLog: (log) => set((state) => ({
    logs: [log, ...state.logs]
  })),

  setLoading: (loading) => set({ isLoading: loading })
}));

