      <div className={clsx("p-3 rounded-xl bg-opacity-10", `bg-${color}-500`)} style={{ backgroundColor: `${color}15` }}>
        <Icon className="w-6 h-6" style={{ color }} />
      </div>
      {trend && (
        <div className={clsx("flex items-center text-xs font-bold px-2 py-1 rounded-full", trend === 'up' ? "bg-green-100 text-green-700" : "bg-red-100 text-red-700")}>
          {trend === 'up' ? <ArrowUpRight className="w-3 h-3 mr-1" /> : <ArrowDownRight className="w-3 h-3 mr-1" />}
          {trendValue}
        </div>
      )}
    </div>
    <div>
      <h3 className="text-3xl font-bold text-slate-900 tabular-nums tracking-tight">{value}</h3>
      <p className="text-sm font-medium text-slate-500 mt-1">{title}</p>
    </div>
  </motion.div>
);

const TankLevel = ({ tank }: { tank: any }) => {
  const percentage = (tank.currentLevel / tank.capacity) * 100;
  const isLow = tank.currentLevel < tank.safeMinLevel;

  return (
    <div className="relative h-48 bg-slate-100 rounded-xl overflow-hidden border border-slate-200 group">
      <motion.div 
        initial={{ height: 0 }}
        animate={{ height: `${percentage}%` }}
        transition={{ type: "spring", bounce: 0, duration: 1.5 }}
        className={clsx(
          "absolute bottom-0 w-full opacity-80 transition-colors duration-500",
          tank.type === FuelType.JET_A1 ? "bg-aviation-500" : "bg-yellow-500"
        )}
      />
      <div className="absolute inset-0 bg-gradient-to-b from-transparent to-black/5" />
      <div className="absolute inset-0 p-4 flex flex-col justify-between z-10">
        <div className="flex justify-between items-start">
           <span className="text-xs font-bold uppercase tracking-wider bg-white/50 backdrop-blur-sm px-2 py-1 rounded-lg text-slate-700">{tank.name}</span>
           {isLow && <AlertTriangle className="w-5 h-5 text-red-600 animate-pulse" />}
        </div>
        <div>
           <p className="text-2xl font-black text-slate-900 tabular-nums drop-shadow-sm">{(tank.currentLevel/1000).toFixed(1)}k</p>
           <p className="text-[10px] font-bold text-slate-500 uppercase">Liters</p>
        </div>
      </div>
    </div>
  );
};

