import { useStore } from './store';
import { toast } from 'sonner';

// Placeholder components for routes not fully rewritten yet but required for navigation
const Placeholder = ({ title }: { title: string }) => (
  <div className="flex items-center justify-center h-96 rounded-2xl border-2 border-dashed border-slate-200">
    <p className="text-slate-400 font-medium">Module: {title} (Coming Soon)</p>
  </div>
);

const App: React.FC = () => {
  const { tanks, updateTankLevel } = useStore();

  // Network Status Toasts
  useEffect(() => {
    const handleOnline = () => toast.success("Back Online", { description: "Data syncing with server." });
    const handleOffline = () => toast.warning("Offline Mode", { description: "Changes saved locally." });

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  return (
    <HashRouter>
      <Routes>
        <Route path="/" element={<Layout />}>
          <Route index element={<Dashboard />} />
          <Route path="intoplane" element={<IntoPlane />} />
          <Route path="forecasting" element={<Forecasting />} />
          <Route 
            path="stock" 
            element={<Stock tanks={tanks} onUpdateTank={updateTankLevel} />} 
          />
          <Route 
            path="bridging" 
            element={<Bridging tanks={tanks} onUpdateTank={updateTankLevel} />} 
          />
          <Route path="admin" element={<SystemAdmin />} />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Route>
      </Routes>
    </HashRouter>
  );
};

