import { FlightLog, User, FlightJob } from '../types';
import { MOCK_JOBS, MOCK_USERS } from '../constants';
import { Clock, CheckCircle, Truck, Play, Pause, AlertTriangle, Wifi, WifiOff, Save, ChevronRight, ChevronLeft, MapPin, User as UserIcon, Lock } from 'lucide-react';

interface IntoPlaneProps {
    user: User;
}

export const IntoPlane: React.FC<IntoPlaneProps> = ({ user }) => {
  const [currentScreen, setCurrentScreen] = useState<'dashboard' | 'timestamps' | 'metering' | 'qc'>('dashboard');
  const [activeFlight, setActiveFlight] = useState<Partial<FlightLog> | null>(null);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [showTopUp, setShowTopUp] = useState(false);
  const [loading, setLoading] = useState(false);

  // Network listener
  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  const startJob = (job: FlightJob) => {
    setActiveFlight({
      flightNumber: job.flightNumber,
      aircraftReg: job.aircraftReg,
      aircraftType: job.aircraftType,
      stand: job.stand,
      vehicleId: 'R-045',
      status: 'PENDING',
      meterOpen: undefined,
      volume: 0,
      panelCheck: false,
      walkAroundCheck: false,
      appearanceCheck: false,
      waterCheck: false,
    });
    setCurrentScreen('timestamps');
  };

  const handleTimestamp = (field: keyof FlightLog) => {
    setActiveFlight(prev => ({
      ...prev,
      [field]: new Date().toISOString()
    }));
  };

  const handleInputChange = (field: keyof FlightLog, value: any) => {
    setActiveFlight(prev => {
      const updated = { ...prev, [field]: value };
      if ((field === 'meterClose' || field === 'meterOpen') && updated.meterClose !== undefined && updated.meterOpen !== undefined) {
        updated.volume = (updated.meterClose as number) - (updated.meterOpen as number);
      }
      return updated;
    });
  };

  const handleSubmit = () => {
    setLoading(true);
    setTimeout(() => {
      setLoading(false);
      alert("Job Completed & Synced!");
      setActiveFlight(null);
      setCurrentScreen('dashboard');
    }, 1500);
  };

  // --- UI Components ---

  const MobileHeader = () => (
    <div className="bg-slate-900 text-white p-4 shadow-md sticky top-0 z-50">
        <div className="flex justify-between items-center">
            <div>
                <h1 className="text-lg font-bold flex items-center">
                    <Truck className="w-5 h-5 mr-2 text-aviation-500" />
                    R-045
                </h1>
                <p className="text-xs text-slate-400">Op: {user.name}</p>
            </div>
            <div className={`flex items-center px-3 py-1 rounded-full text-xs font-bold ${isOnline ? 'bg-green-900 text-green-400 border border-green-700' : 'bg-orange-900 text-orange-400 border border-orange-700'}`}>
                {isOnline ? <Wifi className="w-3 h-3 mr-1"/> : <WifiOff className="w-3 h-3 mr-1"/>}
                {isOnline ? 'SYNCED' : 'OFFLINE'}
            </div>
        </div>
        {activeFlight && (
            <div className="mt-2 pt-2 border-t border-slate-700 flex justify-between items-center text-sm">
                <span className="font-mono text-aviation-400">{activeFlight.flightNumber}</span>
                <span className="text-slate-300">{activeFlight.stand}</span>
                <span className="bg-blue-900 px-2 py-0.5 rounded text-xs">{activeFlight.aircraftReg}</span>
            </div>
        )}
    </div>
  );

  const ScreenDashboard = () => (
    <div className="p-4 space-y-4 pb-24">
        <div className="flex justify-between items-center mb-2">
            <h2 className="text-slate-500 text-sm font-bold uppercase tracking-wide">Shift Schedule</h2>
            <span className="text-xs bg-slate-100 text-slate-500 px-2 py-1 rounded-full">{MOCK_JOBS.length} Flights</span>
        </div>

        {MOCK_JOBS.map((job) => {
            const isAssignedToMe = job.assignedTo === user.id;
            const assignee = MOCK_USERS.find(u => u.id === job.assignedTo);
            const assigneeName = assignee?.name || 'Unassigned';

            return (
                <div key={job.id} className={`bg-white rounded-xl shadow-sm border-l-4 overflow-hidden relative ${isAssignedToMe ? 'border-l-aviation-500 ring-1 ring-aviation-100' : 'border-l-gray-300 opacity-80'}`}>
                    <div className="p-5">
                        <div className="flex justify-between items-center mb-4">
                            <div>
                                <div className="flex items-center space-x-2">
                                     <h3 className="text-2xl font-black text-slate-800">{job.flightNumber}</h3>
                                     <span className="bg-slate-100 px-2 py-1 rounded text-xs font-bold text-slate-600 border border-slate-200">{job.aircraftReg}</span>
                                </div>
                                <div className="flex items-center mt-1 text-slate-500 text-sm">
                                     <MapPin className="w-4 h-4 mr-1 text-aviation-500" />
                                     Stand {job.stand}
                                     <span className="mx-2 text-gray-300">|</span>
                                     <span className="text-xs">{job.aircraftType}</span>
                                </div>
                            </div>
                            <span className={`px-2 py-1 rounded text-xs font-bold uppercase ${
                                job.status === 'COMPLETED' ? 'bg-green-100 text-green-700' : 
                                job.status === 'IN_PROGRESS' ? 'bg-yellow-100 text-yellow-700' : 'bg-gray-100 text-gray-600'
                            }`}>
                                {job.status.replace('_', ' ')}
                            </span>
                        </div>

                        <div className="flex justify-between items-center border-t border-gray-100 pt-4">
                            <div className="flex items-center text-sm">
                                {isAssignedToMe ? (
                                    <div className="flex items-center text-aviation-700 font-bold bg-aviation-50 px-2 py-1 rounded-md">
                                        <UserIcon className="w-4 h-4 mr-2" />
                                        My Task
                                    </div>
                                ) : (
                                    <div className="flex items-center text-slate-400">
                                        <div className="w-6 h-6 rounded-full bg-slate-200 flex items-center justify-center mr-2 text-xs font-bold">
                                            {assigneeName.charAt(0)}
                                        </div>
                                        <span>{assigneeName}</span>
                                    </div>
                                )}
                            </div>

                            <button 
                                onClick={() => startJob(job)}
                                disabled={!isAssignedToMe || job.status === 'COMPLETED'}
                                className={`px-4 py-2 rounded-lg font-bold shadow-sm transition-all flex items-center
                                    ${isAssignedToMe && job.status !== 'COMPLETED'
                                        ? 'bg-aviation-600 active:bg-aviation-700 text-white' 
                                        : 'bg-gray-100 text-gray-400 cursor-not-allowed border border-gray-200'
                                    }
                                `}
                            >
                                {!isAssignedToMe ? <Lock className="w-4 h-4 mr-2" /> : null}
                                {job.status === 'COMPLETED' ? 'VIEW LOG' : (!isAssignedToMe ? 'LOCKED' : 'START JOB')}
                            </button>
                        </div>
                    </div>
                </div>
            );
        })}
    </div>
  );

  const ScreenTimestamps = () => (
    <div className="p-4 flex flex-col h-full min-h-[calc(100vh-140px)]">
        <button onClick={() => setCurrentScreen('dashboard')} className="flex items-center text-slate-500 mb-4 font-bold text-sm">
            <ChevronLeft className="w-4 h-4 mr-1" /> Back to List
        </button>
        <h2 className="text-slate-900 text-xl font-bold mb-6">Ramp Arrival & Setup</h2>

        <div className="space-y-6 flex-1">
            <button 
                onClick={() => handleTimestamp('timestampPosition')}
                disabled={!!activeFlight?.timestampPosition}
                className={`w-full p-8 rounded-2xl border-4 text-left transition-all relative overflow-hidden group shadow-sm
                    ${activeFlight?.timestampPosition 
                        ? 'bg-green-50 border-green-500' 
                        : 'bg-white border-slate-200 active:border-aviation-500 active:bg-aviation-50'}
                `}
            >
                <div className="relative z-10">
                    <span className="block text-sm font-bold uppercase tracking-wider text-slate-500 mb-1">Step 1</span>
                    <span className={`block text-2xl font-black ${activeFlight?.timestampPosition ? 'text-green-700' : 'text-slate-900'}`}>
                        LOG POSITION
                    </span>
                    {activeFlight?.timestampPosition && (
                        <span className="block mt-2 font-mono text-green-600 font-bold flex items-center">
                             <Clock className="w-4 h-4 mr-2"/>
                             {new Date(activeFlight.timestampPosition).toLocaleTimeString()}
                        </span>
                    )}
                </div>
                {!activeFlight?.timestampPosition && <Truck className="absolute right-4 bottom-4 w-12 h-12 text-slate-100 group-active:text-aviation-200" />}
                {activeFlight?.timestampPosition && <CheckCircle className="absolute right-4 bottom-4 w-12 h-12 text-green-200" />}
            </button>

            <button 
                onClick={() => handleTimestamp('timestampStart')}
                disabled={!activeFlight?.timestampPosition || !!activeFlight?.timestampStart}
                className={`w-full p-8 rounded-2xl border-4 text-left transition-all relative overflow-hidden group shadow-sm
                    ${activeFlight?.timestampStart 
                        ? 'bg-green-50 border-green-500' 
                        : !activeFlight?.timestampPosition
                            ? 'bg-slate-100 border-slate-200 opacity-50 cursor-not-allowed'
                            : 'bg-white border-slate-200 active:border-aviation-500 active:bg-aviation-50'}
                `}
            >
                <div className="relative z-10">
                    <span className="block text-sm font-bold uppercase tracking-wider text-slate-500 mb-1">Step 2</span>
                    <span className={`block text-2xl font-black ${activeFlight?.timestampStart ? 'text-green-700' : 'text-slate-900'}`}>
                        COMMENCE FUELING
                    </span>
                     {activeFlight?.timestampStart && (
                        <span className="block mt-2 font-mono text-green-600 font-bold flex items-center">
                             <Clock className="w-4 h-4 mr-2"/>
                             {new Date(activeFlight.timestampStart).toLocaleTimeString()}
                        </span>
                    )}
                </div>
                {!activeFlight?.timestampStart && <Play className="absolute right-4 bottom-4 w-12 h-12 text-slate-100 group-active:text-aviation-200" />}
                {activeFlight?.timestampStart && <CheckCircle className="absolute right-4 bottom-4 w-12 h-12 text-green-200" />}
            </button>
        </div>

        <button 
            onClick={() => setCurrentScreen('metering')}
            disabled={!activeFlight?.timestampStart}
            className="mt-6 w-full bg-slate-900 text-white p-4 rounded-xl font-bold text-lg flex items-center justify-center disabled:opacity-50 disabled:cursor-not-allowed hover:bg-slate-800 transition-colors shadow-lg"
        >
            Proceed to Metering <ChevronRight className="ml-2" />
        </button>
    </div>
  );

  const ScreenMetering = () => (
    <div className="p-4 flex flex-col h-full min-h-[calc(100vh-140px)]">
         <button onClick={() => setCurrentScreen('timestamps')} className="flex items-center text-slate-500 mb-4 font-bold text-sm">
            <ChevronLeft className="w-4 h-4 mr-1" /> Back to Timestamps
         </button>
         <h2 className="text-slate-900 text-xl font-bold mb-6">Metering & Volume</h2>

         <div className="space-y-6">
            <div className="bg-white p-4 rounded-xl shadow-sm border border-gray-200">
                <label className="block text-sm font-bold text-slate-500 uppercase mb-2">Opening Totalizer</label>
                <input 
                    type="number" 
                    className="w-full text-3xl font-mono font-bold p-3 border-2 border-gray-300 rounded-lg focus:border-aviation-500 focus:ring-0 bg-white text-slate-900 placeholder:text-slate-300"
                    placeholder="000000"
                    value={activeFlight?.meterOpen || ''}
                    onChange={(e) => handleInputChange('meterOpen', parseFloat(e.target.value))}
                />
            </div>

            <button 
                onClick={() => handleTimestamp('timestampInitialEnd')}
                disabled={!activeFlight?.meterOpen || !!activeFlight?.timestampInitialEnd}
                className={`w-full p-4 rounded-xl border-2 font-bold flex items-center justify-center transition-colors
                    ${activeFlight?.timestampInitialEnd 
                        ? 'bg-green-100 border-green-500 text-green-800' 
                        : 'bg-white border-slate-300 text-slate-700 hover:bg-gray-50'}`}
            >
                <Pause className="w-5 h-5 mr-2" />
                {activeFlight?.timestampInitialEnd ? `Initial End: ${new Date(activeFlight.timestampInitialEnd).toLocaleTimeString()}` : 'Log Initial End'}
            </button>

            <div className="bg-white p-4 rounded-xl shadow-sm border border-gray-200">
                <label className="block text-sm font-bold text-slate-500 uppercase mb-2">Closing Totalizer</label>
                <input 
                    type="number" 
                    className="w-full text-3xl font-mono font-bold p-3 border-2 border-gray-300 rounded-lg focus:border-aviation-500 focus:ring-0 bg-white text-slate-900 placeholder:text-slate-300"
                    placeholder="000000"
                    value={activeFlight?.meterClose || ''}
                    onChange={(e) => handleInputChange('meterClose', parseFloat(e.target.value))}
                />
            </div>

            <div className="bg-slate-100 p-4 rounded-xl border border-slate-200 text-center">
                 <span className="block text-xs font-bold text-slate-500 uppercase">Net Volume Delivered</span>
                 <span className="block text-4xl font-black text-slate-900 mt-1">{activeFlight?.volume?.toLocaleString() || 0} L</span>
            </div>

            <div className="border-t border-slate-200 pt-4">
                 <button onClick={() => setShowTopUp(!showTopUp)} className="text-aviation-600 font-bold text-sm flex items-center hover:text-aviation-800">
                     {showTopUp ? '- Remove Top-Up' : '+ Add Top-Up'}
                 </button>
                 {showTopUp && (
                     <div className="grid grid-cols-2 gap-4 mt-4 animate-in fade-in slide-in-from-top-2">
                         <button onClick={() => handleTimestamp('timestampFinalStart')} className={`p-3 rounded-lg border font-bold text-sm ${activeFlight?.timestampFinalStart ? 'bg-green-100 border-green-500' : 'bg-white'}`}>
                             {activeFlight?.timestampFinalStart ? 'Started' : 'Final Start'}
                         </button>
                         <button onClick={() => handleTimestamp('timestampFinalEnd')} className={`p-3 rounded-lg border font-bold text-sm ${activeFlight?.timestampFinalEnd ? 'bg-green-100 border-green-500' : 'bg-white'}`}>
                             {activeFlight?.timestampFinalEnd ? 'Ended' : 'Final End'}
                         </button>
                     </div>
                 )}
            </div>
         </div>

         <div className="mt-auto pt-6">
            <button 
                onClick={() => setCurrentScreen('qc')}
                disabled={!activeFlight?.meterClose}
                className="w-full bg-slate-900 text-white p-4 rounded-xl font-bold text-lg flex items-center justify-center disabled:opacity-50 disabled:cursor-not-allowed hover:bg-slate-800 transition-colors shadow-lg"
            >
                Finalize & QC <ChevronRight className="ml-2" />
            </button>
         </div>
    </div>
  );

  const ScreenQC = () => (
    <div className="p-4 flex flex-col h-full min-h-[calc(100vh-140px)]">
         <button onClick={() => setCurrentScreen('metering')} className="flex items-center text-slate-500 mb-4 font-bold text-sm">
            <ChevronLeft className="w-4 h-4 mr-1" /> Back to Metering
         </button>
         <h2 className="text-slate-900 text-xl font-bold mb-6">JIG Compliance Checks</h2>

         <div className="space-y-4 bg-white p-6 rounded-xl shadow-sm border border-gray-200">
            {['panelCheck', 'walkAroundCheck', 'appearanceCheck', 'waterCheck'].map((check) => (
                <label key={check} className="flex items-center p-3 border border-gray-100 rounded-lg hover:bg-slate-50 cursor-pointer">
                    <input 
                        type="checkbox" 
                        checked={!!activeFlight?.[check as keyof FlightLog]} 
                        onChange={(e) => handleInputChange(check as keyof FlightLog, e.target.checked)}
                        className="w-6 h-6 text-aviation-600 rounded focus:ring-aviation-500 border-gray-300"
                    />
                    <span className="ml-3 font-medium text-slate-700 capitalize">
                        {check.replace(/([A-Z])/g, ' $1').trim()}
                    </span>
                </label>
            ))}
         </div>

         <div className="mt-auto pt-6 space-y-4">
             <div className="bg-yellow-50 p-4 rounded-xl border border-yellow-200 text-sm text-yellow-800 flex items-start">
                 <AlertTriangle className="w-5 h-5 mr-2 flex-shrink-0" />
                 <p>By submitting, you certify that all data is accurate and fuel was delivered according to safety regulations.</p>
             </div>

             <button 
                onClick={handleSubmit}
                disabled={loading}
                className="w-full bg-aviation-600 text-white p-4 rounded-xl font-bold text-lg flex items-center justify-center hover:bg-aviation-700 shadow-lg disabled:opacity-70 transition-colors"
             >
                {loading ? 'Syncing...' : (
                    <>
                        <Save className="w-5 h-5 mr-2" />
                        Complete Job
                    </>
                )}
             </button>
         </div>
    </div>
  );

  return (
    <div className="h-full flex flex-col bg-slate-50">
        <MobileHeader />
        <div className="flex-1 overflow-y-auto">
            {currentScreen === 'dashboard' && <ScreenDashboard />}
            {currentScreen === 'timestamps' && <ScreenTimestamps />}
            {currentScreen === 'metering' && <ScreenMetering />}
            {currentScreen === 'qc' && <ScreenQC />}
        </div>
    </div>
  );
};

import React from 'react';
import { User, UserRole } from '../types';
import { 
  LayoutDashboard, 
  Plane, 
  Droplet, 
  TrendingUp, 
  Settings, 
  FileText, 
  LogOut,
  AlertTriangle,
  Database,
  Calendar,
  Anchor,
  Sailboat,
  Hexagon
} from 'lucide-react';

interface SidebarProps {
  user: User;
  activeView: string;
  setActiveView: (view: string) => void;
  onLogout: () => void;
  isMobileMenuOpen: boolean;
}

export const Sidebar: React.FC<SidebarProps> = ({ user, activeView, setActiveView, onLogout, isMobileMenuOpen }) => {
  const getMenuItems = () => {
    switch (user.role) {
      case UserRole.ITP_OPERATOR:
        return [
          { id: 'dashboard', label: 'My Tasks', icon: LayoutDashboard },
          { id: 'intoplane', label: 'Flight Refueling', icon: Plane },
          { id: 'history', label: 'Log History', icon: FileText },
        ];

      case UserRole.ITP_MANAGER:
        return [
          { id: 'dashboard', label: 'Ops Dashboard', icon: LayoutDashboard },
          { id: 'schedule', label: 'Schedule & Assign', icon: Calendar },
          { id: 'history', label: 'Ops History', icon: FileText },
        ];

      case UserRole.DEPOT_OPERATOR:
        return [
          { id: 'dashboard', label: 'Depot Status', icon: LayoutDashboard },
          { id: 'stock', label: 'Tank Levels', icon: Database },
          { id: 'bridging', label: 'Refueler Loading', icon: Droplet },
          { id: 'marine', label: 'Tanker Discharge', icon: Anchor },
          { id: 'seaplane', label: 'Seaplane Ops', icon: Sailboat },
        ];

      case UserRole.DEPOT_MANAGER:
        return [
          { id: 'dashboard', label: 'Depot Dashboard', icon: LayoutDashboard },
          { id: 'stock', label: 'Stock Reconciliation', icon: Database },
          { id: 'bridging', label: 'Transfer Oversight', icon: Droplet },
          { id: 'marine', label: 'Marine Oversight', icon: Anchor },
          { id: 'seaplane', label: 'Seaplane Oversight', icon: Sailboat },
        ];

      case UserRole.EXECUTIVE:
      case UserRole.COMMERCIAL:
        return [
          { id: 'dashboard', label: 'Executive Overview', icon: LayoutDashboard },
          { id: 'forecasting', label: 'Forecasting & Trends', icon: TrendingUp },
          { id: 'reports', label: 'Commercial Reports', icon: FileText },
        ];

      case UserRole.ADMIN:
      default:
        return [
          { id: 'dashboard', label: 'Ops Dashboard', icon: LayoutDashboard },
          { id: 'admin', label: 'System Admin', icon: Settings },
          { id: 'intoplane', label: 'Into-Plane Ops', icon: Plane },
          { id: 'stock', label: 'Stock Management', icon: Database },
          { id: 'forecasting', label: 'Forecasting', icon: TrendingUp },
          { id: 'reports', label: 'Commercial Reports', icon: FileText },
        ];
    }
  };

  const menuItems = getMenuItems();

  return (
    <aside className={`
      fixed inset-y-0 left-0 z-50 w-64 bg-aviation-900 text-white transform transition-transform duration-300 ease-in-out
      ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0 lg:static lg:inset-0 shadow-xl
    `}>
      <div className="h-full flex flex-col">
        {/* Brand */}
        <div className="h-16 flex items-center px-6 bg-aviation-800 font-bold text-xl tracking-wider border-b border-aviation-700">
          <Hexagon className="w-6 h-6 mr-2 text-aviation-500" />
          MACL <span className="text-aviation-500 ml-1">FMS</span>
        </div>

        {/* User Profile Snippet */}
        <div className="p-6 border-b border-aviation-800 bg-aviation-800/50">
          <div className="flex items-center space-x-3">
            <img src={user.avatar} alt="User" className="w-10 h-10 rounded-full border-2 border-aviation-500" />
            <div>
              <p className="font-semibold text-sm">{user.name}</p>
              <p className="text-xs text-aviation-200 capitalize">{user.role.replace('_', ' ')}</p>
            </div>
          </div>
        </div>

        {/* Navigation */}
        <nav className="flex-1 px-4 py-6 space-y-1 overflow-y-auto">
          {menuItems.map((item) => {
            const Icon = item.icon;
            const isActive = activeView === item.id;
            return (
              <button
                key={item.id}
                onClick={() => setActiveView(item.id)}
                className={`w-full flex items-center px-4 py-3 text-sm font-medium rounded-lg transition-colors
                  ${isActive 
                    ? 'bg-aviation-600 text-white shadow-md' 
                    : 'text-aviation-100 hover:bg-aviation-800 hover:text-white'
                  }`}
              >
                <Icon className="w-5 h-5 mr-3" />
                {item.label}
              </button>
            );
          })}
        </nav>

        {/* System Status / Logout */}
        <div className="p-4 border-t border-aviation-800 bg-aviation-900">
           {/* Mock Alert Status */}
          <div className="mb-4 flex items-center px-4 py-2 bg-aviation-800 rounded-md text-xs text-yellow-400">
            <AlertTriangle className="w-3 h-3 mr-2" />
            <span>2 Critical Alerts Active</span>
          </div>

          <button
            onClick={onLogout}
            className="w-full flex items-center px-4 py-2 text-sm text-aviation-200 hover:text-white hover:bg-aviation-800 rounded-lg transition-colors"
          >
            <LogOut className="w-5 h-5 mr-3" />
            Sign Out
          </button>
        </div>
      </div>
    </aside>
  );
};

import React, { useState } from 'react';
import { Sailboat, MapPin, Droplet, Save, CheckCircle, AlertTriangle } from 'lucide-react';

export const Seaplane: React.FC = () => {
    const [loading, setLoading] = useState(false);
    const [success, setSuccess] = useState(false);

    // High contrast inputs for better visibility on tablets
    const inputClass = "w-full p-4 border border-gray-300 rounded-lg focus:ring-2 focus:ring-aviation-500 focus:border-aviation-500 bg-white text-slate-900 placeholder:text-slate-400 font-medium text-lg transition-shadow";
    const labelClass = "block text-sm font-bold text-slate-700 mb-2 uppercase tracking-wide";

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        setTimeout(() => {
            setLoading(false);
            setSuccess(true);
        }, 1500);
    };

    if (success) {
        return (
             <div className="flex flex-col items-center justify-center h-full p-8 text-center animate-in fade-in zoom-in duration-300 bg-slate-50 min-h-[600px]">
                <div className="w-24 h-24 bg-green-100 rounded-full flex items-center justify-center mb-6 ring-8 ring-green-50">
                  <CheckCircle className="w-12 h-12 text-green-600" />
                </div>
                <h2 className="text-3xl font-bold text-slate-900 mb-2">Daily Log Submitted</h2>
                <p className="text-slate-600 max-w-md text-lg">
                  Hydrant volume for the operator has been successfully recorded and synced to the central inventory.
                </p>
                <button 
                  onClick={() => { setSuccess(false); }}
                  className="mt-8 px-8 py-3 text-aviation-600 font-bold hover:bg-aviation-50 rounded-lg border-2 border-aviation-200 bg-white shadow-sm transition-colors text-lg"
                >
                  Submit Another Log
                </button>
              </div>
        );
    }

    return (
        <div className="p-4 lg:p-8 max-w-5xl mx-auto">
            <div className="flex items-center mb-8 p-6 bg-white rounded-xl border border-gray-200 shadow-sm">
                <div className="p-4 bg-blue-50 rounded-full mr-5 border border-blue-100">
                    <Sailboat className="w-10 h-10 text-blue-600" />
                </div>
                <div>
                    <h2 className="text-3xl font-bold text-slate-900">Seaplane Daily Operations</h2>
                    <p className="text-slate-500 text-lg">End-of-day Hydrant Volume Recording</p>
                </div>
            </div>

            <form onSubmit={handleSubmit} className="bg-white p-8 rounded-xl shadow-sm border border-gray-200">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-8">
                     {/* Operator Selection */}
                     <div>
                        <label className={labelClass}>Seaplane Operator</label>
                        <select className={inputClass} required>
                            <option value="">Select Operator...</option>
                            <option value="TMA">Trans Maldivian (TMA)</option>
                            <option value="Manta">Manta Air</option>
                            <option value="Flyme">Flyme</option>
                        </select>
                     </div>

                     {/* Dock Location */}
                     <div>
                        <label className={labelClass}>Dock Location</label>
                        <div className="relative">
                            <MapPin className="absolute left-4 top-4 w-6 h-6 text-gray-400" />
                            <select className={`${inputClass} pl-12`} required>
                                <option value="">Select Dock...</option>
                                <option>Terminal A - Dock 1</option>
                                <option>Terminal A - Dock 2</option>
                                <option>Terminal B - Dock 1</option>
                                <option>Terminal B - Dock 2</option>
                                <option>Floating Dock C</option>
                            </select>
                        </div>
                    </div>

                    {/* Hydrant/Pump ID */}
                    <div>
                        <label className={labelClass}>Hydrant / Pump ID</label>
                         <input required type="text" className={inputClass} placeholder="e.g. HP-01" />
                    </div>

                    {/* Fuel Type Readonly */}
                     <div>
                        <label className={labelClass}>Product</label>
                        <div className="w-full p-4 bg-slate-50 border border-gray-200 rounded-lg text-slate-700 font-bold flex items-center text-lg h-[62px]">
                            <Droplet className="w-6 h-6 mr-3 text-aviation-600" />
                            Jet A-1
                        </div>
                     </div>
                </div>

                {/* Volume Input - Prominent */}
                <div className="mb-8 p-6 bg-slate-50 rounded-xl border border-slate-200">
                    <label className={labelClass}>Total Daily Volume (Liters)</label>
                    <div className="relative">
                        <input 
                            required 
                            type="number" 
                            min="1"
                            className="w-full text-5xl font-black p-6 border-2 border-slate-300 rounded-xl focus:ring-4 focus:ring-aviation-500/20 focus:border-aviation-500 bg-white text-slate-900 placeholder:text-slate-300 text-right pr-28 transition-all" 
                            placeholder="0" 
                        />
                        <span className="absolute right-8 top-1/2 transform -translate-y-1/2 text-2xl font-bold text-slate-400">LITERS</span>
                    </div>
                    <p className="text-slate-500 text-sm mt-3 flex items-center font-medium">
                        <AlertTriangle className="w-4 h-4 mr-2 text-orange-500" />
                        Please verify the closing meter reading matches the entered volume before submission.
                    </p>
                </div>

                <div className="flex justify-end">
                    <button 
                        type="submit" 
                        disabled={loading}
                        className="w-full md:w-auto px-10 py-4 bg-aviation-600 text-white rounded-xl font-bold text-xl hover:bg-aviation-700 shadow-lg flex items-center justify-center transition-transform active:scale-[0.98] disabled:opacity-70 disabled:cursor-not-allowed"
                    >
                        {loading ? 'Processing...' : (
                            <>
                                <Save className="w-6 h-6 mr-3" />
                                Submit Daily Log
                            </>
                        )}
                    </button>
                </div>
            </form>
        </div>
    );
};
